class Hoppla {
  public static void main( String[] str ) {
    int max = 30;
    int anzahl = 0;
    for (int i = 5; i <= max; i++) {
      boolean ersetzt = false;
      if (i % 7 == 0) {          // Vielfaches von 7
        System.out.print("hop");
        ersetzt = true;
      }
      if (i % 9 == 0) {          // Vielfaches von 9 -- kein else, damit "hoppla" möglich ist
        System.out.print("pla");
        ersetzt = true;
      }
      if (ersetzt) {             // mindestens eine Ersetzung: Zeile abschließen und zählen
        anzahl++;
        System.out.println();
      } else {
        System.out.println(i);   // keine Ersetzung: die Zahl selbst ausgeben
      }
    }
    System.out.println("Anzahl: " + anzahl);
  }
}

