class Dreieck {
  public static void main( String[] str ) {
    int size = 6;
    System.out.println("Dreieck von Groesse " + size + ":");
    if (size < 3) {
      System.out.println("zu klein");
    } else {
      for (int zeile = 0; zeile < size; zeile++) {       // eine Zeile pro Durchlauf
        for (int leer = 0; leer < zeile; leer++) {       // zeile viele Leerzeichen
          System.out.print(" ");
        }
        for (int x = 0; x < size - zeile; x++) {         // size-zeile viele X
          System.out.print("X");
        }
        System.out.println();                            // Zeile abschließen
      }
    }
  }
}

